(function(){
function decode(value){if(!value)return null;try{var text=decodeURIComponent(Array.prototype.map.call(atob(value.replace(/-/g,"+").replace(/_/g,"/")),function(c){return "%"+("00"+c.charCodeAt(0).toString(16)).slice(-2);}).join(""));return JSON.parse(text);}catch(e){return null;}}
function encode(value){var bytes=unescape(encodeURIComponent(JSON.stringify(value)));return btoa(bytes).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,"");}
function el(tag,className,text){var node=document.createElement(tag);if(className)node.className=className;if(text!==undefined)node.textContent=text;return node;}
function money(value,currency){var number=Number(value)||0;try{return new Intl.NumberFormat("sr-RS",{style:"currency",currency:currency&&currency.length===3?currency:"RSD",maximumFractionDigits:2}).format(number);}catch(e){return number.toFixed(2)+" "+(currency||"RSD");}}
function clip(value,max){value=String(value||"").trim();return value.length>max?value.slice(0,max):value;}
document.querySelectorAll(".wf-instance[data-wf-component=\"product-detail\"]").forEach(function(host){
if(host.dataset.wfDetailReady==="true")return;
host.dataset.wfDetailReady="true";
var root=host.querySelector(".wf-detail");
if(!root)return;
var status=root.querySelector("[data-wf-status]"),panel=root.querySelector("[data-wf-product]"),gallery=root.querySelector("[data-wf-gallery]"),meta=root.querySelector("[data-wf-meta]"),name=root.querySelector("[data-wf-name]"),price=root.querySelector("[data-wf-price]"),stock=root.querySelector("[data-wf-stock]"),description=root.querySelector("[data-wf-description]"),specs=root.querySelector("[data-wf-specs]"),specBody=root.querySelector("[data-wf-spec-body]"),related=root.querySelector("[data-wf-related]"),relatedGrid=root.querySelector("[data-wf-related-grid]");
if(host.hasAttribute("data-wf-provider-preview")||host.hasAttribute("data-wf-provider-preview-error"))host.dataset.wfCatalogBridge="true";
var pendingId="",serial=0;
function requestId(){serial+=1;var suffix=Math.random().toString(36).replace(/[^a-z0-9]/g,"").slice(0,8);var prefix=("00000000"+serial.toString(36)).slice(-8);return (prefix+suffix).slice(0,40);}
function productId(){var params=new URLSearchParams(window.location.search);var id=clip(params.get("id"),80);if(!id||id.indexOf("/")>=0||id.indexOf("\\")>=0)return"";return id;}
function showStatus(text,error){if(panel)panel.hidden=true;status.textContent=text;if(error)status.dataset.error="true";else status.removeAttribute("data-error");}
function render(data){if(!data||data.found!==true){showStatus("Proizvod nije pronađen.",true);return;}status.textContent="";status.removeAttribute("data-error");panel.hidden=false;while(meta.firstChild)meta.removeChild(meta.firstChild);var links=[];function catalogLink(href,label){var anchor=el("a","wf-detail__link",label);anchor.href=href;return anchor;}if(data.brand)links.push(catalogLink("/proizvodi?df="+encodeURIComponent("field11:"+data.brand),data.brand));if(data.category)links.push(catalogLink("/proizvodi?category="+encodeURIComponent(data.category),data.category));links.forEach(function(link,index){if(index)meta.appendChild(document.createTextNode(" · "));meta.appendChild(link);});meta.hidden=!links.length;name.textContent=data.name||data.id||"";price.textContent=money(data.price,data.currency);var known=data["stock-known"]!==false;stock.textContent=known?(Number(data.stock)>0?"Na stanju: "+data.stock:"Nema na stanju"):"Stanje na upit";stock.dataset.empty=known&&Number(data.stock)<=0?"true":"false";var text=String(data.description||"").trim();description.textContent=text;description.hidden=!text;gallery.innerHTML="";var images=Array.isArray(data.gallery)&&data.gallery.length?data.gallery:[{url:"/commonAssets/Images/coming_soon_transparent.png"}];var main=el("img","wf-detail__image");function show(url,alt){main.src=url||"";main.alt=alt||"";}show(images[0].url,data.name||"");gallery.appendChild(main);if(images.length>1){var thumbs=el("div","wf-detail__thumbs");images.forEach(function(image,index){var button=el("button","wf-detail__thumb"),thumb=el("img");button.type="button";if(index===0)button.setAttribute("aria-current","true");thumb.src=image.url||"";thumb.alt="";button.appendChild(thumb);button.addEventListener("click",function(){show(image.url,data.name||"");thumbs.querySelectorAll("button").forEach(function(other){other.removeAttribute("aria-current");});button.setAttribute("aria-current","true");});thumbs.appendChild(button);});gallery.appendChild(thumbs);}specBody.innerHTML="";var rows=Array.isArray(data.characteristics)?data.characteristics:[];rows.forEach(function(row){var tr=el("tr");tr.appendChild(el("th","",row.name||""));tr.appendChild(el("td","",row.value||""));specBody.appendChild(tr);});specs.hidden=!rows.length;while(relatedGrid.firstChild)relatedGrid.removeChild(relatedGrid.firstChild);var others=Array.isArray(data.related)?data.related:[];others.forEach(function(item){if(!item||!item.id)return;var card=el("a","wf-detail__card");card.href="/proizvod?id="+encodeURIComponent(item.id);var image=el("img");image.src=item["image-url"]||"/commonAssets/Images/coming_soon_transparent.png";image.alt=item.name||"";image.loading="lazy";card.appendChild(image);var body=el("span","wf-detail__card-body");if(item.brand)body.appendChild(el("span","wf-detail__card-brand",item.brand));body.appendChild(el("strong","",item.name||item.id));body.appendChild(el("span","",money(item.price,item.currency)));card.appendChild(body);relatedGrid.appendChild(card);});related.hidden=!relatedGrid.children.length;}
function load(){var id=productId();if(!id){showStatus("Proizvod nije izabran.",true);return;}var request=requestId();pendingId=request;status.textContent="Učitavanje…";status.removeAttribute("data-error");if(panel)panel.hidden=true;var input={id:id};if(host.dataset.wfCatalogBridge==="true"){window.parent.postMessage({type:"elastyc-webfront-catalog-provider-v1",pageKey:host.dataset.wfPage||"",instanceKey:host.dataset.wfInstance||"",input:input,requestId:request},"*");return;}var url=new URL(host.dataset.wfProviderUrl,window.location.href);url.searchParams.set("wf_input",encode(input));fetch(url.toString(),{credentials:"same-origin",headers:{Accept:"application/json"}}).then(function(response){if(!response.ok)throw new Error("HTTP "+response.status);return response.json();}).then(function(payload){if(pendingId!==request)return;render(payload.data!==undefined?payload.data:payload);}).catch(function(error){if(pendingId!==request)return;showStatus(error&&error.message?error.message:"Proizvod trenutno nije dostupan.",true);});}
window.addEventListener("message",function(event){if(event.source!==window.parent)return;var data=event.data;if(!data||data.type!=="elastyc-webfront-catalog-provider-result-v1")return;if(data.requestId!==pendingId||data.instanceKey!==host.dataset.wfInstance)return;if(!data.ok){showStatus(data.error||"Proizvod trenutno nije dostupan.",true);return;}render(data.data);});
if(!productId()){showStatus("Proizvod nije izabran.",true);return;}
var previewError=host.dataset.wfProviderPreviewError||"";
if(previewError){showStatus(previewError,true);return;}
load();
});
})();
